SELECT   id, local_id, api_code, id_card, cell, cus_num, usertype, `name`, pd_cell_type, pd_cell_province,
        device_add_status, push_status, `status`, is_del, create_time, update_time, extend,
        data_message, create_date
FROM b_umeng_data
WHERE id > #{lastSearchId}
  AND local_id in (0,#{localId})
  AND api_code =#{apiCode}
  AND device_add_status in (-1,1)
  AND status = 1
  AND is_del = 1

    AND create_time >=#{searchStartTime} 

ORDER BY id ASC
LIMIT #{searchSize}

SELECT  id, local_id, api_code, id_card, cell, cus_num, usertype, `name`, pd_cell_type, pd_cell_province,
        device_add_status, push_status, `status`, is_del, create_time, update_time, extend,
        data_message, create_date
FROM b_umeng_data
WHERE id > #{lastSearchId}
  AND local_id = #{localId}
  AND api_code = #{apiCode}
  AND push_status in (-1,1)
  AND status = 1
  AND is_del = 1
ORDER BY id ASC
LIMIT #{searchSize}

SELECT   id, local_id, api_code, id_card, cell, cus_num, usertype, `name`, pd_cell_type, pd_cell_province,
         device_add_status, push_status, `status`, is_del, create_time, update_time, extend,
         data_message, create_date
FROM b_umeng_data
WHERE local_id=#{localId}
  and cell = #{cell}

